package com.fasterxml.jackson.core.base;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser.Feature;
import com.fasterxml.jackson.core.io.IOContext;
import com.fasterxml.jackson.core.io.NumberInput;
import com.fasterxml.jackson.core.json.DupDetector;
import com.fasterxml.jackson.core.json.JsonReadContext;
import com.fasterxml.jackson.core.json.PackageVersion;
import com.fasterxml.jackson.core.util.ByteArrayBuilder;
import com.fasterxml.jackson.core.util.TextBuffer;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import java.util.Arrays;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for ParserBase#convertNumberToInt.
 * Since the method and fields are protected, we use a Test subclass to expose them.
 */
public class ParserBase_convertNumberToInt_TriageGen1Test {

    // Constants mimicking the internal state of ParserBase for testing purposes
    private static final int NR_LONG = 1;
    private static final int NR_BIGINT = 2;
    private static final int NR_DOUBLE = 4;
    private static final int NR_BIGDECIMAL = 8;
    private static final int NR_INT = 16;

    private static final BigInteger BI_MIN_INT = BigInteger.valueOf(Integer.MIN_VALUE);
    private static final BigInteger BI_MAX_INT = BigInteger.valueOf(Integer.MAX_VALUE);
    private static final BigDecimal BD_MIN_INT = new BigDecimal(Integer.MIN_VALUE);
    private static final BigDecimal BD_MAX_INT = new BigDecimal(Integer.MAX_VALUE);
    private static final double MIN_INT_D = (double) Integer.MIN_VALUE;
    private static final double MAX_INT_D = (double) Integer.MAX_VALUE;

    private TestableParserBase parser;

    @Before
    public void setUp() {
        parser = new TestableParserBase(new IOContext(), 0);
    }

    /**
     * Concrete implementation of ParserBase to allow testing protected members.
     */
    private static class TestableParserBase extends ParserBase {
        int _numTypesValid = 0;
        long _numberLong = 0;
        BigInteger _numberBigInt = BigInteger.ZERO;
        double _numberDouble = 0.0;
        BigDecimal _numberBigDecimal = BigDecimal.ZERO;
        int _numberInt = 0;

        // Mocking constants found in the actual class
        protected final int NR_LONG = 1;
        protected final int NR_BIGINT = 2;
        protected final int NR_DOUBLE = 4;
        protected final int NR_BIGDECIMAL = 8;
        protected final int NR_INT = 16;
        protected final BigInteger BI_MIN_INT = BigInteger.valueOf(Integer.MIN_VALUE);
        protected final BigInteger BI_MAX_INT = BigInteger.valueOf(Integer.MAX_VALUE);
        protected final BigDecimal BD_MIN_INT = new BigDecimal(Integer.MIN_VALUE);
        protected final BigDecimal BD_MAX_INT = new BigDecimal(Integer.MAX_VALUE);
        protected final double MIN_INT_D = (double) Integer.MIN_VALUE;
        protected final double MAX_INT_D = (double) Integer.MAX_VALUE;

        protected TestableParserBase(IOContext ctxt, int features) {
            super(ctxt, features);
        }

        @Override
        protected void _closeInput() throws IOException {}
        @Override
        protected void _releaseBuffers() throws IOException {}

        @Override
        protected void _reportError(String msg) throws IOException {
            throw new IOException(msg);
        }

        @Override
        protected void reportOverflowInt() throws IOException {
            throw new IOException("Overflow");
        }

        @Override
        protected void _throwInternal() throws IOException {
            throw new IOException("Internal Error");
        }

        @Override
        public String getText() {
            return "testValue";
        }

        // Expose the protected method for testing
        public void callConvertNumberToInt() throws IOException {
            super.convertNumberToInt();
        }
    }

    @Test
    public void testConvertLongSuccess() throws IOException {
        parser._numTypesValid = parser.NR_LONG;
        parser._numberLong = 12345L;
        parser.callConvertNumberToInt();
        assertEquals(12345, parser._numberInt);
        assertEquals(parser.NR_LONG | parser.NR_INT, parser._numTypesValid);
    }

    @Test(expected = IOException.class)
    public void testConvertLongOutOfRange() throws IOException {
        parser._numTypesValid = parser.NR_LONG;
        parser._numberLong = (long) Integer.MAX_VALUE + 1L;
        parser.callConvertNumberToInt();
    }

    @Test
    public void testConvertBigIntSuccess() throws IOException {
        parser._numTypesValid = parser.NR_BIGINT;
        parser._numberBigInt = BigInteger.valueOf(500);
        parser.callConvertNumberToInt();
        assertEquals(500, parser._numberInt);
    }

    @Test(expected = IOException.class)
    public void testConvertBigIntOverflow() throws IOException {
        parser._numTypesValid = parser.NR_BIGINT;
        parser._numberBigInt = BigInteger.valueOf(Integer.MAX_VALUE).add(BigInteger.ONE);
        parser.callConvertNumberToInt();
    }

    @Test(expected = IOException.class)
    public void testConvertBigIntUnderflow() throws IOException {
        parser._numTypesValid = parser.NR_BIGINT;
        parser._numberBigInt = BigInteger.valueOf(Integer.MIN_VALUE).subtract(BigInteger.ONE);
        parser.callConvertNumberToInt();
    }

    @Test
    public void testConvertDoubleSuccess() throws IOException {
        parser._numTypesValid = parser.NR_DOUBLE;
        parser._numberDouble = 123.45;
        parser.callConvertNumberToInt();
        assertEquals(123, parser._numberInt);
    }

    @Test(expected = IOException.class)
    public void testConvertDoubleOverflow() throws IOException {
        parser._numTypesValid = parser.NR_DOUBLE;
        parser._numberDouble = MAX_INT_D + 1.0;
        parser.callConvertNumberToInt();
    }

    @Test(expected = IOException.class)
    public void testConvertDoubleUnderflow() throws IOException {
        parser._numTypesValid = parser.NR_DOUBLE;
        parser._numberDouble = MIN_INT_D - 1.0;
        parser.callConvertNumberToInt();
    }

    @Test
    public void testConvertBigDecimalSuccess() throws IOException {
        parser._numTypesValid = parser.NR_BIGDECIMAL;
        parser._numberBigDecimal = new BigDecimal("999.99");
        parser.callConvertNumberToInt();
        assertEquals(999, parser._numberInt);
    }

    @Test(expected = IOException.class)
    public void testConvertBigDecimalOverflow() throws IOException {
        parser._numTypesValid = parser.NR_BIGDECIMAL;
        parser._numberBigDecimal = new BigDecimal(Integer.MAX_VALUE).add(BigDecimal.ONE);
        parser.callConvertNumberToInt();
    }

    @Test(expected = IOException.class)
    public void testConvertBigDecimalUnderflow() throws IOException {
        parser._numTypesValid = parser.NR_BIGDECIMAL;
        parser._numberBigDecimal = new BigDecimal(Integer.MIN_VALUE).subtract(BigDecimal.ONE);
        parser.callConvertNumberToInt();
    }

    @Test(expected = IOException.class)
    public void testConvertNoValidType() throws IOException {
        parser._numTypesValid = 0;
        parser.callConvertNumberToInt();
    }
}
